const needle = require('needle')

function PesquisaHandler() {
  this.exibir = (req, res) => {
    if (req.query.simbolo) {
      const url = req.query.url + req.query.simbolo
      return needle.get(url, (erro, resposta, corpo) => {
        res.send(corpo)
      })
    }
  }
}

module.exports = PesquisaHandler
